#!/usr/bin/env python3
"""Build an audited, self-contained reading export from real saved records."""
import hashlib
from html import escape as e
import json
from pathlib import Path
import shutil
import sys

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from scripts.validate import validate
from scripts.learning_pages import curriculum, oncall

BASE='/mysql-lab/'
ORIGIN='https://lynnlee1229.github.io'
REPO='https://github.com/lynnlee1229/mysql-lab'


def text(en,zh,lang):return zh if lang=='zh' else en
def block(value):return '<pre><code>'+e(value)+'</code></pre>'
def table(headers,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join('<th scope="col">'+e(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(c))+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'


BLOCK_0=block('A: START TRANSACTION;\nA: SELECT value FROM a WHERE id=1;             -- 100\nB: UPDATE a SET value=200 WHERE id=1; COMMIT;\nA: SELECT value FROM a WHERE id=1;             -- RC: 200 / RR: 100\nA: SELECT value FROM a WHERE id=1 FOR UPDATE;  -- 200 in both\nA: SELECT value FROM a WHERE id=1;             -- RC: 200 / RR: 100\nB: UPDATE a SET value=300 WHERE id=1;          -- waits for A\nA: COMMIT;                                  -- B can finish')
BLOCK_1=block('colima start --profile mysql-lab --cpu 2 --memory 2 --disk 12 --activate=false\nexport DOCKER_CONTEXT=colima-mysql-lab')
BLOCK_2=block('python lab.py stop       # retains the named data volume\npython lab.py start      # uses the same credentials and volume\npython lab.py run        # resets only the synthetic experiment tables\n\n# Explicitly destructive: removes only this Lab project and data volume\npython lab.py destroy --confirm lynn-mysql-lab')
BLOCK_3=block('python -m unittest discover -s tests -v\npython scripts/validate.py records/run-clean.json records/run-repeat.json\npython scripts/build_site.py\npython scripts/check_site.py\npython -m http.server 18911 --bind 127.0.0.1 --directory dist')

def shell(lang,page,title,desc,body,interactive=False):
    t=lambda a,b:text(a,b,lang)
    suffix='' if page=='index' else page+'/'
    url=ORIGIN+BASE+lang+'/'+suffix
    other='zh' if lang=='en' else 'en'
    nav=''.join(f'<a href="{BASE}{lang}/{("" if p=="index" else p+"/")}"'+(' aria-current="page"' if p==page else '')+'>'+label+'</a>' for p,label in [('index',t('Workbench','实验记录')),('learn',t('Course route','课程路线')),('oncall',t('Concurrency exercise','并发练习')),('guide',t('Run locally','本地运行')),('methods',t('Methods & scope','方法与范围'))])
    return f'''<!doctype html><html lang="{lang if lang=='en' else 'zh-CN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · MySQL Lab · Lynn Lee</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#19333b"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="en" href="{ORIGIN}{BASE}en/{suffix}"><link rel="alternate" hreflang="zh-CN" href="{ORIGIN}{BASE}zh/{suffix}"><link rel="alternate" hreflang="x-default" href="{ORIGIN}{BASE}en/{suffix}"><link rel="icon" href="{BASE}assets/rick-favicon.ico"><link rel="stylesheet" href="{BASE}assets/site.css">{('<script defer src="'+BASE+'assets/site.js"></script>') if interactive else ''}</head><body><a class="offscreen" href="#main">{t('Skip to content','跳至正文')}</a><header><div class="top"><a class="brand" href="{t('/','/zh/')}"><img src="{BASE}assets/rick-avatar.jpeg" width="38" height="38" alt=""><span>Lynn Lee<small>MYSQL / LEARNING LAB</small></span></a><nav aria-label="{t('Main navigation','主导航')}">{nav}<a data-language href="{BASE}{other}/{suffix}" lang="{other}">{t('中文','English')}</a></nav></div></header><main class="wrap" id="main">{body}</main><footer><div class="wrap"><span>Lynn Lee · MySQL Lab 1.1 · {t('Synthetic data. Measured records.','合成数据，真实执行记录。')}</span><span><a href="{t('/websites/','/zh/websites/')}">{t('All tools & Labs','工具与实验室')}</a> · <a href="{REPO}">GitHub / MIT</a> · <a href="{BASE}sitemap.xml">Sitemap</a></span></div></footer></body></html>'''


def workbench(lang,r):
    t=lambda a,b:text(a,b,lang)
    d=r['deadlock']; idx=r['indexes']; version=r['environment']['version']; rows=idx['variants'][0]['result_rows']
    isol=table([t('Isolation','隔离级别'),t('First plain read','首次普通读'),t('After B commits','B 提交后普通读'),t('FOR UPDATE','锁定读'),t('Plain read again','再一次普通读')], [[x['level'],x['ordinary_first'],x['ordinary_after_B_commit'],x['locking_read'],x['ordinary_after_locking_read']] for x in r['isolation']])
    variants=''.join(f'<option value="{v["id"]}">{v["id"]}</option>' for v in idx['variants'])
    body=f'''<div class="hero"><div><p class="eyebrow">01 / MYSQL {e(version)} · INNODB</p><h1>{t('See what the database<br>actually did.','看清数据库<br>实际做了什么。')}</h1><p class="lead">{t('Two sessions. Real lock waits. A rolled-back transaction. Inspect saved evidence, then reproduce the experiment locally.','两个会话、真实锁等待、被回滚的事务。先检查保存证据，再在本地复现实验。')}</p><a class="button primary" href="{BASE}{lang}/guide/">{t('Run the local Lab','运行本地实验')} ↗</a></div><div class="diagram" aria-label="{t('Experiment architecture','实验架构')}"><div class="actors"><div class="actor"><strong>A</strong>{t('session / transaction','会话 / 事务')}</div><div class="actor"><strong>B</strong>{t('session / transaction','会话 / 事务')}</div></div><div class="engine">↓ SQL / InnoDB / a + b + events ↑</div><small>{t('Observer → data_locks + data_lock_waits<br>Coordinator → explicit execution barriers<br>Website → saved JSON, no database connection','观察者 → data_locks + data_lock_waits<br>编排器 → 明确执行屏障<br>网页 → 保存的 JSON，不连接数据库')}</small></div></div>
<div class="status" id="record-status" role="status">{t('Saved real run, not a live server.','真实运行的保存记录，并非在线数据库。')} <span class="record-time">{e(r['recorded_at'])}</span></div>
<div class="toolbar"><label>{t('Saved evidence','保存的实测记录')}<select id="record-select"><option value="clean">{t('Clean volume run','干净数据卷首跑')}</option><option value="repeat">{t('Repeat after stop / start','停止并重启后复跑')}</option></select></label><span class="spacer"></span><a class="button" id="download-json" href="{BASE}records/run-clean.json" download="mysql-lab-run.json">{t('Download run JSON','下载运行 JSON')}</a><button id="export-csv">{t('Export query samples CSV','导出查询采样 CSV')}</button><button id="share">{t('Copy deep link','复制当前深链')}</button></div>
<div class="jump"><a href="#deadlock">01 {t('Locks & deadlock','锁与死锁')}</a><a href="#isolation">02 {t('Isolation & reads','隔离与读取')}</a><a href="#indexes">03 {t('Indexes & plans','索引与计划')}</a><a href="#evidence">{t('Version & evidence','版本与证据')}</a></div>
<div class="metrics"><div class="metric"><strong id="victim-count">1 / 2</strong><span>{t('transactions rolled back by deadlock detection','死锁检测回滚的事务')}</span></div><div class="metric"><strong>100 → 200</strong><span>{t('snapshot vs locking read under RR','RR 下快照读与锁定读的差异')}</span></div><div class="metric"><strong>{idx['row_count']:,}</strong><span>{t('seeded synthetic rows · 7 samples per query','固定种子合成行 · 每种查询 7 次采样')}</span></div></div>
<section class="lab-section" id="deadlock"><div class="section-intro"><div><span class="section-number">EXPERIMENT 01</span><h2>{t('A wait becomes a cycle.','等待如何形成环。')}</h2></div><p class="muted">{t('A updates a; B updates b. A requests b and waits. Only after the observer sees A → B in the real wait table does B request a. InnoDB chooses a victim. The consistent-order control still waits, but both transactions commit.','A 更新 a，B 更新 b。A 请求 b 并等待；观察者在真实锁等待表看到 A → B 后，才允许 B 请求 a。InnoDB 选择一个事务回滚。同顺序对照仍会等待，但两个事务均提交。')}</p></div>
<div class="grid2"><div class="panel"><h3>{t('Observed outcome','实际事务结果')}</h3><div id="outcomes">{table(['Case','A','B'],[['Cycle',d['outcomes']['A']['status'],d['outcomes']['B']['status']],['Same order','committed','committed']])}</div><p class="subtle">{t('Victim identity is an observation, not a fixed API contract. Final values: cycle 101/101; ordered control 102/102.','被回滚的是哪一方属于本次观察，不是固定接口保证。终值：死锁 101/101，同顺序对照 102/102。')}</p></div><div class="panel"><h3>{t('Actual latest-deadlock excerpt','最近死锁记录的实际摘录')}</h3><pre id="deadlock-excerpt">{e(chr(10).join(d['deadlock_excerpt']))}</pre><p class="subtle">{t('Allowlisted excerpt of SHOW ENGINE INNODB STATUS. Raw connection and environment lines stay local.','摘自 SHOW ENGINE INNODB STATUS 的白名单行。原始连接与环境行仅留本地。')}</p></div></div>
<div class="toolbar" id="timeline"><label>{t('Inspect recorded timeline','检查保存的执行时间线')}<select id="case-select"><option value="deadlock">{t('Opposite order / deadlock','反向加锁 / 死锁')}</option><option value="control">{t('Same order / no cycle','同顺序 / 无环')}</option><option value="rc">READ COMMITTED</option><option value="rr">REPEATABLE READ</option></select></label></div>
<div class="grid2"><div class="panel"><h3>{t('Step through executed statements','逐步检查真实执行的语句')}</h3><div class="stepper"><button id="previous" aria-label="{t('Previous step','上一步')}">←</button><input id="step" type="range" min="1" max="{len(d['timeline'])}" value="{len(d['timeline'])}" aria-label="{t('Timeline step','时间线步骤')}"><button id="next" aria-label="{t('Next step','下一步')}">→</button><output id="step-label"></output></div><ol class="timeline" id="timeline-list"><li>{t('JavaScript enables step inspection; all original events are in the downloadable JSON.','启用 JavaScript 后可逐步检查；全部原始事件均可从 JSON 下载。')}</li></ol></div><div class="panel"><h3>{t('Captured lock wait','采集到的锁等待')}</h3><div id="wait-edges"><div class="waiting">A → B / b / PRIMARY / X,REC_NOT_GAP</div></div><p class="subtle" id="snapshot-note">{t('This snapshot precedes cycle closure. The detector resolves the complete cycle immediately; the deadlock excerpt supplies its evidence. Thread IDs are mapped to session A/B; memory-address lock IDs are excluded.','此快照位于死锁环闭合之前。检测器会立即解除完整环；完整环的证据来自死锁摘录。线程 ID 映射为会话 A/B，不公开内存地址形式的锁 ID。')}</p><div id="lock-table">{table(['Actor','Table','Type','Mode','Status'],[[x['actor'],x['OBJECT_NAME'],x['LOCK_TYPE'],x['LOCK_MODE'],x['LOCK_STATUS']] for x in d['snapshot_before_cycle']['locks']])}</div></div></div></section>
<section class="lab-section" id="isolation"><div class="section-intro"><div><span class="section-number">EXPERIMENT 02</span><h2>{t('One transaction. Two read rules.','同一事务，两种读取规则。')}</h2></div><p class="muted">{t('A establishes a plain-read snapshot at 100. B changes the row to 200 and commits. A repeats the plain read, then reads FOR UPDATE, then repeats the plain read again. A does not modify the row.','A 先普通读取 100，建立读视图。B 将该行改为 200 并提交。A 再普通读，再 FOR UPDATE，再普通读。A 在此期间不修改该行。')}</p></div><div id="isolation-table">{isol}</div><p class="notice">{t('Both locking reads observe 200 and block B’s later update to 300 until A commits. Under RR, the following plain read still sees the original 100. This exact-row experiment does not establish gap-lock, phantom, DML or SERIALIZABLE behavior.','两种隔离级别的锁定读都看到 200，并阻塞 B 随后改为 300 的写入，直到 A 提交。RR 下之后的普通读仍看到原来的 100。本实验只检验主键精确行读取，不能推广到间隙锁、幻读、DML 或 SERIALIZABLE。')}</p>{BLOCK_0}</section>
<section class="lab-section" id="indexes"><div class="section-intro"><div><span class="section-number">EXPERIMENT 03</span><h2>{t('A plan is a claim. Execute it.','查看计划，也检查实际执行。')}</h2></div><p class="muted">{t('Fixed seed 20261113. Compare a full scan, a composite index, covering projection and a month-expression rewrite. Result hashes prove equivalence within each comparison; timing is machine-specific evidence.','固定种子 20261113。比较全表扫描、联合索引、覆盖投影及月份表达式改写。每组比较以结果哈希验证等价，耗时仅代表此次机器实测。')}</p></div><div class="grid2"><div class="panel"><h3>{t('Client wall time / median ms','客户端耗时 / 中位数 ms')}</h3><div id="timing-bars"></div><p class="subtle">{t('One warm-up + seven measured fetches per variant. Warm shared buffer pool; no cache flush. Fixed sequential order, no randomized crossover. p95 is nearest-rank, with only seven samples.','每种查询 1 次预热、7 次实际取回结果采样。共享暖缓冲池，不清缓存。固定顺序，无随机交叉设计。p95 为最近秩法，仅 7 个样本。')}</p></div><div class="panel"><h3>{t('Keep comparison boundaries clear','明确比较的边界')}</h3><p>{t(f'All variants select the same {rows} IDs and dates. full_scan and composite_noncover also return amount_cents; covering projection deliberately omits that field. composite_cover and expression_month have identical full results.',f'所有方案返回相同的 {rows} 个 ID 和日期。full_scan 与 composite_noncover 还读取 amount_cents；覆盖投影有意省略该字段。composite_cover 与 expression_month 的完整结果一致。')}</p><p class="subtle">{t('Secondary InnoDB indexes contain the primary key. (tenant_id, status, created_at) therefore covers id and created_at, but not amount_cents. DATE_FORMAT requires filtering more candidate index rows than the half-open date range in this dataset.','InnoDB 二级索引包含主键。因此 (tenant_id, status, created_at) 可覆盖 id 与 created_at，但无法覆盖 amount_cents。在此数据中，DATE_FORMAT 比半开日期范围需要筛选更多索引候选行。')}</p></div></div>
<div class="toolbar"><label>{t('Plan / actual execution / result','计划 / 实际执行 / 结果')}<select id="variant-select">{variants}</select></label><span id="query-summary" class="subtle"></span></div><h3>SQL</h3><pre id="query-sql">{e(idx['variants'][0]['sql'])}</pre><h3>EXPLAIN ANALYZE</h3><pre id="analyze-plan">{e(idx['variants'][0]['explain_analyze'])}</pre><details><summary>EXPLAIN FORMAT=JSON</summary><pre id="json-plan">{e(json.dumps(idx['variants'][0]['explain_json'],indent=2))}</pre></details><details><summary>{t('Seven measured samples and full returned rows','7 次耗时采样与全部返回行')}</summary><pre id="query-rows">{e(json.dumps(idx['variants'][0]['rows'],default=str,indent=2))}</pre></details><details><summary>{t('Schema and index DDL','表结构与索引 DDL')}</summary>{block(r['schema_sql']+chr(10)+idx['index_ddl']+';')}</details></section>
<section class="lab-section" id="evidence"><span class="section-number">PROVENANCE / LIMITS</span><h2>{t('Evidence you can inspect and rerun.','可检查，也可重新运行的证据。')}</h2><div class="grid2"><div class="panel"><h3>{t('Executed failure paths','实际执行的故障路径')}</h3><p>{t('Bad SQL → 1064. Real blocked update → lock wait timeout 1205. Reserved non-listening loopback port → connection error 2003. Explicit rollback, joined workers and zero remaining Lab locks are asserted.','错误 SQL → 1064；真实阻塞更新 → 锁等待超时 1205；保留但未监听的回环端口 → 连接错误 2003。显式回滚、工作线程退出、Lab 锁数归零均有断言。')}</p><a href="{BASE}records/verification.json">{t('Lifecycle & verification record','生命周期与验收记录')} ↗</a></div><div class="panel"><h3>{t('Version and experiment limits','版本与实验边界')}</h3><p id="environment-summary">MySQL {e(version)} · {e(r['environment']['runtime'])} · {t('2 CPU / 1 GiB container limit','容器上限 2 核 / 1 GiB')} · {r['environment']['buffer_pool_bytes']//1024//1024} MiB buffer pool.</p><p class="subtle">{t('Synthetic data only. No remote database, model calls or uploaded records. Website controls inspect saved executions; they do not execute SQL.','仅使用合成数据。没有远程数据库、模型调用或上传记录。网页控件用于检查保存的执行，不会执行 SQL。')}</p><a href="{BASE}{lang}/methods/">{t('Read methods, scope and official references','阅读方法、范围与官方参考')} →</a></div></div><noscript><p class="notice">{t('The original evidence and guides are readable without JavaScript. Enable JavaScript for timeline and plan selection.','无需 JavaScript 也可阅读原始证据和指南。时间线及计划选择需要 JavaScript。')}</p></noscript></section>'''
    route=f'<p class="notice"><a href="{BASE}{lang}/learn/">{t("Start with six course-mapped learning units", "从六个课程对应学习单元开始")}</a> · <a href="{BASE}{lang}/oncall/">{t("New: both transactions commit, but the business invariant fails", "新增：事务都提交，业务不变量仍失败")}</a></p>'
    return shell(lang,'index',t('See what the database actually did','看清数据库实际做了什么'),t('Real MySQL deadlocks, read views and query plans, with saved evidence and a reproducible local kit.','真实 MySQL 死锁、读视图与查询计划，附保存证据及可复现本地实验。'),route+body,True)


def guide(lang,image):
    t=lambda a,b:text(a,b,lang)
    setup='git clone https://github.com/lynnlee1229/mysql-lab.git\ncd mysql-lab\npython3 -m venv .venv\nsource .venv/bin/activate\npython -m pip install -r requirements.txt\npython lab.py doctor\npython lab.py start --port 13316\npython lab.py run\npython lab.py stop'
    body=f'''<article class="prose"><p class="eyebrow">LOCAL RUNBOOK / 15–25 MIN</p><h1>{t('Make the evidence yours.','亲手获得实验结果。')}</h1><p class="lead">{t('Use two real sessions and an observer on your own machine. The companion repository is public because changing SQL and debugging concurrency are part of this learning workflow.','在自己的机器上运行两个真实会话与一个观察者。修改 SQL 与调试并发是学习流程的一部分，因此配套实验仓库公开。')}</p><h2>01 / {t('Prepare an isolated runtime','准备隔离运行环境')}</h2><p>{t('Requirements: Python 3.11+, Docker Engine and Compose v2 or standalone docker-compose. Reserve two CPU cores, 2 GiB available engine memory and at least 2 GiB free disk. The database container is capped at 2 CPUs / 1 GiB. No paid services are needed.','要求 Python 3.11+、Docker Engine 与 Compose v2 或独立 docker-compose。为引擎预留 2 核、2 GiB 内存，磁盘至少空闲 2 GiB。数据库容器限制为 2 核 / 1 GiB。无需付费服务。')}</p><p>{t('Use an existing healthy engine, or create a dedicated Colima profile on macOS. Never clean unrelated volumes to make space. If using the profile below, retain DOCKER_CONTEXT for every Lab command.','可使用健康的现有引擎，或在 macOS 新建专用 Colima profile。不要清理其他实验卷来腾空间。使用下方 profile 时，每条 Lab 命令都应保留 DOCKER_CONTEXT。')}</p>{BLOCK_1}<h2>02 / {t('Start, run and stop','启动、运行、停止')}</h2>{block(setup)}<p>{t('start generates random passwords in ignored .local/ with restricted file permissions, creates only the lynn-mysql-lab Compose project and binds 127.0.0.1:13316. Choose a free port on first start. Do not connect this runner to an existing business database: run deliberately drops and rebuilds its own mysql_lab tables.','start 在忽略提交的 .local/ 中生成随机密码，限制文件权限，仅创建 lynn-mysql-lab Compose 项目，并绑定 127.0.0.1:13316。首次启动可选择其他空闲端口。不要将运行器连接到业务数据库：run 会删除并重建专用 mysql_lab 的实验表。')}</p><p>{t('A successful run writes a timestamped sanitized run.json under .local/runs/. The full raw InnoDB deadlock text is in raw-local-only/ and is never copied to the website. Failed runs exit nonzero and do not produce a success report.','成功运行会在 .local/runs/ 下保存带时间戳、已筛选字段的 run.json。完整 InnoDB 死锁原文位于 raw-local-only/，不会复制到网页。失败运行返回非零状态，不会生成成功报告。')}</p><h2>03 / {t('Predict, inspect, change','预测、检查、修改')}</h2><ol class="sql-list"><li>{t('Predict which second UPDATE waits. Find the observer barrier, the real data_lock_waits edge, error 1213 and the two final values. Compare the ordered control.','预测哪条第二次 UPDATE 会等待。检查观察屏障、真实 data_lock_waits 边、1213 错误和最终数值，再比较同顺序对照。')}</li><li>{t('Predict four read values under each isolation level. Inspect plain reads before and after FOR UPDATE. Check that B’s later writer actually waits.','预测每个隔离级别下四次读取的数值。检查 FOR UPDATE 前后的普通读取，并确认 B 的后续写入真实等待。')}</li><li>{t('Compare full scan versus indexed noncovering SQL with identical hashes. Compare covering range versus DATE_FORMAT using identical projection and hashes. Read actual rows in EXPLAIN ANALYZE before interpreting timings.','比较全表扫描与联合索引非覆盖查询的相同哈希；比较覆盖范围查询与 DATE_FORMAT 的相同投影及哈希。解释耗时前先阅读 EXPLAIN ANALYZE 的 actual rows。')}</li></ol><p>{t('Modify scripts/experiments.py only after preserving a baseline report. Change the locking order or query predicate, rerun, and compare actual evidence. Fixed seeds preserve the data; optimizer and hardware behavior can still differ.','先保留基线报告，再修改 scripts/experiments.py 的加锁顺序或查询条件，复跑并比较实际证据。固定种子保留数据，优化器与硬件行为仍可能不同。')}</p><h2>04 / {t('Preserve or explicitly destroy','保留数据或显式销毁')}</h2>{BLOCK_2}<p>{t('Do not delete .local/config.json or compose.env while retaining the database volume: its persisted passwords must match. stop does not stop your Docker engine. With a dedicated profile, stop this Lab first, then optionally run colima stop --profile mysql-lab.','保留数据库卷时不要删除 .local/config.json 或 compose.env：密码必须与卷内保存的一致。stop 不停止 Docker 引擎。使用专用 profile 时，先停止 Lab，再按需执行 colima stop --profile mysql-lab。')}</p><h2>05 / {t('Build the reading site and verify','构建阅读站并验证')}</h2>{BLOCK_3}<p>{t('Open http://127.0.0.1:18911/mysql-lab/en/. The exporter reads only committed allowlisted records and site assets. It never scans .local/, raw logs, environment files or the homepage source.','访问 http://127.0.0.1:18911/mysql-lab/en/。导出器仅读取已提交的白名单记录与网页资源，不扫描 .local/、原始日志、环境文件或主页源码。')}</p><details><summary>{t('Pinned image and troubleshooting','固定镜像与故障排查')}</summary>{block(image)}<p>{t('doctor reports missing engine, Compose, driver or disk space. start fails visibly on occupied ports or initialization failure. Connection refusal: check the selected context and start. Error 1205: inspect the saved timeout case. Assertion failure: retain local evidence and rerun after stop/start; do not substitute expected values.','doctor 检查引擎、Compose、驱动与磁盘。端口占用或初始化失败会使 start 明确失败。连接拒绝时检查 context 并启动引擎。1205 请检查保存的超时案例。断言失败时保留本地证据并停止/重启后复跑，不要用预期数值替换结果。')}</p></details><p><a class="button primary" href="{REPO}">{t('Open the public companion repository','打开公开配套实验仓库')} ↗</a></p></article>'''
    route=f'<p class="notice"><a href="{BASE}{lang}/learn/">{t("Choose a lecture and runnable learning unit", "选择具体讲次与可运行学习单元")}</a> · <a href="{BASE}{lang}/oncall/">{t("Run the new editable SQL concurrency exercise", "运行新增的可改 SQL 并发练习")}</a></p>'
    return shell(lang,'guide',t('Run the local MySQL Lab','本地运行 MySQL Lab'),t('A scoped local Docker workflow with generated credentials, explicit barriers and repeatable results.','隔离 Docker、随机凭据、执行屏障与可复现结果的本地工作流。'),route+body)


def methods(lang,r):
    t=lambda a,b:text(a,b,lang)
    body=f'''<article class="prose"><p class="eyebrow">METHOD / VERSION / LIMITS</p><h1>{t('Know what the record proves.','明确证据能说明什么。')}</h1><p class="lead">{t('The website is a reader for actual saved MySQL executions. A local runner creates evidence; a strict exporter publishes selected fields. No browser control starts a database.','网页用于阅读实际保存的 MySQL 执行。本地运行器采集证据，严格导出器只发布选定字段。网页控件不会启动数据库。')}</p><h2>{t('Barriers and deadlock evidence','屏障与死锁证据')}</h2><p>{t('The coordinator waits for both first updates to return, submits A’s second update in its own worker, and polls data_lock_waits with a hard deadline. B’s second update is released only after a real A → B edge appears. Polling uses a short wait between observations; elapsed time never decides statement ordering.','编排器等待两边首次更新完成，在独立工作线程提交 A 的第二条更新，并在硬截止时间内轮询 data_lock_waits。真实 A → B 边出现后，才放行 B 的第二条更新。两次观测之间短暂等待，但经过时间从不决定语句顺序。')}</p><p>{t('The automatic deadlock detector stays enabled. Therefore the saved lock-table snapshot shows the wait before the cycle, not a frozen complete cycle. SHOW ENGINE INNODB STATUS, error 1213, transaction outcomes and final table values jointly establish the deadlock. The same-order control observes a real wait and both commits, distinguishing waiting from cyclic waiting.','自动死锁检测保持开启。因此锁表快照显示成环前的等待，不是冻结的完整环。SHOW ENGINE INNODB STATUS、1213 错误、事务结果和表终值共同证明死锁。同顺序对照观察真实等待与双方提交，区分等待和环形等待。')}</p><details><summary>{t('Actual observer SQL','观察者的实际 SQL')}</summary>{block(r['collector_sql']['locks'])}{block(r['collector_sql']['waits'])}</details><h2>{t('Read views and locking reads','读视图与锁定读')}</h2><p>{t('Explicit transactions, InnoDB, an existing unique primary-key row and no writes by reader A. The first ordinary SELECT establishes A’s snapshot. Under READ COMMITTED, each ordinary read can observe B’s committed 200; under REPEATABLE READ, ordinary reads retain 100. SELECT FOR UPDATE observes current committed 200 in both and holds a row lock that blocks B’s later writer.','前提是显式事务、InnoDB、已存在的唯一主键行，且读取方 A 不写入。首次普通 SELECT 建立 A 的读视图。READ COMMITTED 的后续普通读可看到 B 已提交的 200；REPEATABLE READ 的普通读保留 100。SELECT FOR UPDATE 在两者下都读取当前已提交的 200，并持有阻塞 B 后续写入的行锁。')}</p><p>{t('This does not test ranges, missing keys, gap locks, phantom inserts, own writes, UPDATE read behavior, autocommit locking reads, or other isolation levels. Do not apply this result to every statement.','这里不检验范围、缺失键、间隙锁、幻影插入、自身写入、UPDATE 的读取行为、自动提交锁定读及其他隔离级别。不要将观察推广到所有语句。')}</p><h2>{t('Seeded data and timing protocol','固定数据与耗时协议')}</h2><p>{t('Python Random seed 20261113 generates 60,000 rows: 64 uniformly sampled tenants, status weights 7:2:1, dates uniformly sampled over 365 days in 2026, synthetic payload and integer cents. The full generated-row SHA-256 is recorded. ANALYZE TABLE updates statistics before each index condition.','Python Random 种子 20261113 生成 60,000 行：64 个均匀抽样租户，状态权重 7:2:1，2026 年 365 天均匀抽样日期、合成载荷及整数分金额。记录完整生成行的 SHA-256。每种索引条件前执行 ANALYZE TABLE 更新统计。')}</p><p>{t('Each query has one untimed warm-up and seven measured client executions including fetch, followed by separate EXPLAIN FORMAT=JSON and EXPLAIN ANALYZE executions. The latter executes SQL and reports server iterator timings/row counts. All seven result hashes must match. The noncovering pair and covering rewrite pair must each have equal result hashes.','每条查询先进行 1 次不计时预热、7 次包含取回结果的客户端实测，再独立执行 EXPLAIN FORMAT=JSON 与 EXPLAIN ANALYZE。后者会执行 SQL，报告服务端迭代器耗时/行数。7 次结果哈希必须一致，非覆盖比较组与覆盖改写组各自的结果哈希也必须一致。')}</p><p>{t('No cold-cache test, concurrency load test, randomized ordering, capacity estimate or production recommendation is claimed. Timings include local client/network overhead and are sensitive to buffer state, virtualization, hardware and optimizer statistics. Seven samples make p95 coarse.','不声称完成冷缓存测试、并发负载测试、随机顺序实验、容量估计或生产建议。耗时包括本地客户端/网络开销，并受缓冲池、虚拟化、硬件及优化器统计影响。仅 7 个样本，p95 粒度较粗。')}</p><h2>{t('Provenance and source boundary','来源与源码边界')}</h2>{block(json.dumps(r['environment'],ensure_ascii=False,indent=2))}<p>{t('The first record came from a fresh named volume; the repeat followed stop/start with the same volume. Semantic assertions and dataset hashes match; transaction victim, lock order in snapshots, estimates and timings can vary. Raw host/connection lines, passwords, paths and memory-address lock IDs are excluded from the public JSON. Session thread IDs become A/B labels.','首份记录来自全新命名卷；复跑在同一卷停止/重启后执行。语义断言和数据集哈希一致；回滚对象、快照锁顺序、估计与耗时允许变化。公开 JSON 不含原始主机/连接行、密码、路径和内存地址形式的锁 ID，线程 ID 映射为 A/B。')}</p><p>{t('The MIT companion contains synthetic SQL, orchestration, tests and sanitized records so learners can download, develop and debug it. The complete homepage source remains private. This site does not collect files, connect to a public database or call paid models.','MIT 配套仓库仅包含合成 SQL、编排器、测试及筛选记录，供学习者下载、开发、调试。主页整体源码保持私有。本站不收集文件、不连接公开数据库、不调用付费模型。')}</p><h2>{t('Official references','官方参考')}</h2><ul><li><a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-deadlock-example.html">MySQL 8.4 · An InnoDB Deadlock Example</a></li><li><a href="https://dev.mysql.com/doc/refman/8.4/en/performance-schema-data-lock-waits-table.html">MySQL 8.4 · data_lock_waits</a></li><li><a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-transaction-isolation-levels.html">MySQL 8.4 · Transaction Isolation Levels</a></li><li><a href="https://dev.mysql.com/doc/refman/8.4/en/explain.html">MySQL 8.4 · EXPLAIN / EXPLAIN ANALYZE</a></li><li><a href="https://hub.docker.com/_/mysql">Docker Official Image · MySQL</a></li></ul><p><a href="{BASE}records/verification.json">{t('Machine-readable verification and record hashes','机器可读验收与记录哈希')} ↗</a></p></article>'''
    return shell(lang,'methods',t('Methods, versions and scope','方法、版本与范围'),t('How real barriers, read-view experiments and warm query measurements were executed, and their limits.','真实屏障、读视图实验、暖缓存查询采样的执行方法与限制。'),body)


def main():
    records={}
    for name in ('run-clean.json','run-repeat.json'):
        r=json.loads((ROOT/'records'/name).read_text());validate(r);records[name]=r
    assert records['run-clean.json']['indexes']['dataset_sha256']==records['run-repeat.json']['indexes']['dataset_sha256']
    out=ROOT/'dist'/'mysql-lab'
    if out.exists():shutil.rmtree(out)
    (out/'assets').mkdir(parents=True)
    for name in ('site.css','site.js','learning.js','rick-avatar.jpeg','rick-favicon.ico'):
        shutil.copy2(ROOT/'site'/name,out/'assets'/name)
    (out/'records').mkdir()
    for name in ('run-clean.json','run-repeat.json','verification.json','oncall-clean.json','oncall-repeat.json','oncall-verification.json','course-verification.json'):
        shutil.copy2(ROOT/'records'/name,out/'records'/name)
    (out/'learning').mkdir()
    shutil.copy2(ROOT/'learning/resources.json',out/'learning/resources.json')
    r=records['run-clean.json'];urls=[]
    for lang in ('en','zh'):
        for page,html in [('index',workbench(lang,r)),('guide',guide(lang,r['environment']['image'])),('methods',methods(lang,r)),('learn',curriculum(lang,shell,block,table)),('oncall',oncall(lang,shell,block,table))]:
            path=out/lang/('' if page=='index' else page)
            path.mkdir(parents=True,exist_ok=True);(path/'index.html').write_text(html)
            urls.append(ORIGIN+BASE+lang+'/'+('' if page=='index' else page+'/'))
    (out/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=/mysql-lab/en/"><title>MySQL Lab</title><link rel="canonical" href="https://lynnlee1229.github.io/mysql-lab/en/"></head><body><a href="/mysql-lab/en/">MySQL Lab · English</a> · <a href="/mysql-lab/zh/">中文</a></body></html>')
    (out/'sitemap.xml').write_text('<?xml version="1.0" encoding="utf-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in urls)+'</urlset>')
    files={str(f.relative_to(out)):hashlib.sha256(f.read_bytes()).hexdigest() for f in out.rglob('*') if f.is_file()}
    (out/'manifest.json').write_text(json.dumps({'format':'mysql-lab-static/v1','files':files},indent=2)+'\n')
    print('PASS: bilingual measured workbench, course route, runnable concurrency exercise, guides and audited evidence built.')


if __name__=='__main__':main()
